import AppKit
import UniformTypeIdentifiers

/// Where a chime comes from. Settings store a sound as a key with a prefix:
/// "app:Singing Bowl", "system:Glass", "custom:my-bell.m4a". A key with no
/// prefix is a macOS sound, as saved by earlier versions.
enum SoundSource {
    case app, system, custom
}

/// Plays chimes from Tiempo Pomo's own pack, the macOS alert sounds, or files
/// the user added, at the app's own volume.
@MainActor
enum Sound {
    // MARK: Catalogue

    /// Tiempo Pomo's own pack, generated by scripts/make_sounds.swift.
    static let appNames = [
        "Singing Bowl", "Soft Bell", "Bright Ding", "Rising Chimes", "Gentle Gong",
        "Marimba Up", "Marimba Down", "Kalimba", "Wood Blocks", "Triple Beep",
    ]

    static let systemNames: [String] = {
        let dir = URL(fileURLWithPath: "/System/Library/Sounds")
        let files = (try? FileManager.default.contentsOfDirectory(at: dir, includingPropertiesForKeys: nil)) ?? []
        let found = files.map { $0.deletingPathExtension().lastPathComponent }.sorted()
        return found.isEmpty
            ? ["Basso", "Blow", "Bottle", "Frog", "Funk", "Glass", "Hero", "Morse", "Ping", "Pop", "Purr", "Sosumi", "Submarine", "Tink"]
            : found
    }()

    static var appKeys: [String] { appNames.map { "app:" + $0 } }
    static var systemKeys: [String] { systemNames.map { "system:" + $0 } }

    /// Files the user added, kept in the app's own (sandboxed) Application Support.
    static var customDirectory: URL {
        let base = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
        return base.appendingPathComponent("Sounds", isDirectory: true)
    }

    static func customKeys() -> [String] {
        let files = (try? FileManager.default.contentsOfDirectory(at: customDirectory, includingPropertiesForKeys: nil)) ?? []
        return files
            .filter { !$0.lastPathComponent.hasPrefix(".") }
            .map { "custom:" + $0.lastPathComponent }
            .sorted { $0.localizedStandardCompare($1) == .orderedAscending }
    }

    static func source(of key: String) -> SoundSource {
        if key.hasPrefix("app:") { return .app }
        if key.hasPrefix("custom:") { return .custom }
        return .system
    }

    static func displayName(_ key: String) -> String {
        let name = key.split(separator: ":", maxSplits: 1).last.map(String.init) ?? key
        return source(of: key) == .custom ? (name as NSString).deletingPathExtension : name
    }

    private static func load(_ key: String) -> NSSound? {
        let name = key.split(separator: ":", maxSplits: 1).last.map(String.init) ?? key
        switch source(of: key) {
        case .app:
            guard let url = Bundle.main.url(forResource: name, withExtension: "wav", subdirectory: "Sounds") else { return nil }
            return NSSound(contentsOf: url, byReference: true)
        case .custom:
            return NSSound(contentsOf: customDirectory.appendingPathComponent(name), byReference: true)
        case .system:
            return NSSound(named: NSSound.Name(name))?.copy() as? NSSound
        }
    }

    // MARK: Playing

    /// NSSound stops when released, so the ones still ringing are held here.
    private static var playing: [NSSound] = []
    private static var pending: [DispatchWorkItem] = []

    /// Rings a sound `times` times, each ring starting once the last has
    /// mostly finished, so long sounds don't pile up and short ones don't
    /// blur together.
    static func play(_ key: String, volume: Double, times: Int = 1) {
        guard volume > 0, let probe = load(key) else { return }
        let gap = min(max(probe.duration * 0.8, 0.7), 3.0)
        for i in 0..<max(1, times) {
            let work = DispatchWorkItem {
                MainActor.assumeIsolated {
                    guard let sound = load(key) else { return }
                    sound.volume = Float(volume)
                    playing.removeAll { !$0.isPlaying }
                    playing.append(sound)
                    sound.play()
                }
            }
            pending.append(work)
            DispatchQueue.main.asyncAfter(deadline: .now() + Double(i) * gap, execute: work)
        }
        pending.removeAll { $0.isCancelled }
    }

    /// Silences whatever is ringing and any repeats still to come.
    static func stopAll() {
        pending.forEach { $0.cancel() }
        pending.removeAll()
        playing.forEach { $0.stop() }
        playing.removeAll()
    }

    // MARK: Your sounds

    enum ImportError: LocalizedError {
        case unreadable(String), tooLong(String), tooBig(String)

        var errorDescription: String? {
            switch self {
            case .unreadable(let n): return "\(n) isn't an audio file Tiempo Pomo can play."
            case .tooLong(let n): return "\(n) is longer than 30 seconds. Chimes need to be short."
            case .tooBig(let n): return "\(n) is larger than 20 MB."
            }
        }
    }

    static let maxSeconds: TimeInterval = 30
    static let maxBytes = 20 * 1024 * 1024

    /// Copies an audio file the user picked into the app's own folder and
    /// returns its key. Only files chosen in the Open panel are readable here.
    static func importSound(from url: URL) throws -> String {
        let name = url.lastPathComponent
        let size = (try? url.resourceValues(forKeys: [.fileSizeKey]).fileSize) ?? 0
        guard size <= maxBytes else { throw ImportError.tooBig(name) }
        guard let sound = NSSound(contentsOf: url, byReference: true), sound.duration > 0 else {
            throw ImportError.unreadable(name)
        }
        guard sound.duration <= maxSeconds else { throw ImportError.tooLong(name) }

        let fm = FileManager.default
        try fm.createDirectory(at: customDirectory, withIntermediateDirectories: true)
        let base = url.deletingPathExtension().lastPathComponent
        let ext = url.pathExtension
        var dest = customDirectory.appendingPathComponent(name)
        var n = 2
        while fm.fileExists(atPath: dest.path) {
            dest = customDirectory.appendingPathComponent("\(base) \(n)").appendingPathExtension(ext)
            n += 1
        }
        try fm.copyItem(at: url, to: dest)
        return "custom:" + dest.lastPathComponent
    }

    static func deleteCustom(_ key: String) {
        guard source(of: key) == .custom else { return }
        let file = customDirectory.appendingPathComponent(displayFileName(key))
        try? FileManager.default.removeItem(at: file)
    }

    private static func displayFileName(_ key: String) -> String {
        key.split(separator: ":", maxSplits: 1).last.map(String.init) ?? key
    }

    static let importTypes: [UTType] = [.audio]
}
